import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadPlayfair = makeLoadFont('PlayfairDisplay');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: playfairFamily } = loadPlayfair();



export type BuildingFromTheGroundUpProps = Record<string, any>;

const BuildingFromTheGroundUp: React.FC<BuildingFromTheGroundUpProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "Building from the ground up",
  subtitle = "Solid foundations for future growth and scalable architecture.",
  textColor = "#09090b",
  blockColor = "#f4f4f5",
  accentColor = "#2563eb",
  gridColor = "#a1a1aa",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout Configuration
  // Split Layout: Text on the left (5% to 35%), Buildings on the right (40% to 95%)
  const numCols = 8;
  const floorCounts = [3, 5, 4, 7, 6, 10, 9, 13]; // Ascending skyline trend
  const canvasAreaWidth = width * 0.55;
  const marginLeft = width * 0.4;
  const gap = 16 * s;
  const colWidth = (canvasAreaWidth - (numCols - 1) * gap) / numCols;
  const floorHeight = 32 * s;
  const floorGap = 8 * s;
  const baseBottom = height * 0.85;

  // Pre-calculate blocks to ensure pure function rendering
  const blocks = useMemo(() => {
    const data = [];
    let blockIndex = 0;
    for (let c = 0; c < numCols; c++) {
      const floors = floorCounts[c];
      for (let f = 0; f < floors; f++) {
        const x = marginLeft + c * (colWidth + gap);
        const y = baseBottom - (f + 1) * (floorHeight + floorGap);
        // Sweeping wave effect: bottom-to-top, left-to-right
        const delay = 30 + f * 4 + c * 3;
        // Assign accent color to a few strategic blocks for visual interest
        const isAccent = blockIndex === 12 || blockIndex === 27 || blockIndex === 45;
        data.push({
          id: `block-${c}-${f}`,
          x,
          y,
          width: colWidth,
          height: floorHeight,
          delay,
          isAccent,
        });
        blockIndex++;
      }
    }
    return data;
  }, [marginLeft, colWidth, gap, baseBottom, floorHeight, floorGap]);

  // Global Animations
  const gridOpacity = interpolate(frame, [0, 20], [0, 0.4], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const lineDelay = 20;
  const lineProgress = spring({
    frame: frame - lineDelay,
    fps,
    config: { damping: 15 },
  });
  const lineWidth = interpolate(lineProgress, [0, 1], [0, canvasAreaWidth], {
    extrapolateLeft: "clamp",
  });

  const scaffoldingDelay = 10;
  const scaffoldingProgress = spring({
    frame: frame - scaffoldingDelay,
    fps,
    config: { damping: 20 },
  });
  const maxScaffoldHeight = height * 0.6;

  const titleProgress = spring({
    frame: frame - 45,
    fps,
    config: { damping: 12 },
  });
  const titleY = interpolate(titleProgress, [0, 1], [40 * s, 0], {
    extrapolateLeft: "clamp",
  });
  const titleOpacity = interpolate(titleProgress, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
  });

  const subtitleProgress = spring({
    frame: frame - 55,
    fps,
    config: { damping: 12 },
  });
  const subtitleY = interpolate(subtitleProgress, [0, 1], [30 * s, 0], {
    extrapolateLeft: "clamp",
  });
  const subtitleOpacity = interpolate(subtitleProgress, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
  });

  const accentLineProgress = spring({
    frame: frame - 35,
    fps,
    config: { damping: 14 },
  });
  const accentLineWidth = interpolate(accentLineProgress, [0, 1], [0, 60 * s], {
    extrapolateLeft: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* Blueprint Grid Background */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", opacity: gridOpacity, transition: "none" }}
      >
        <defs>
          <pattern
            id="blueprint-grid"
            width={60 * s}
            height={60 * s}
            patternUnits="userSpaceOnUse"
          >
            <path
              d={`M ${60 * s} 0 L 0 0 0 ${60 * s}`}
              fill="none"
              stroke={gridColor}
              strokeWidth={1 * s}
              strokeOpacity={0.15}
              style={{ transition: "none" }}
            />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#blueprint-grid)" />
      </svg>

      {/* Scaffolding Lines */}
      {Array.from({ length: numCols }).map((_, c) => (
        <div
          key={`scaffold-${c}`}
          style={{
            position: "absolute",
            left: marginLeft + c * (colWidth + gap) + colWidth / 2 - 1 * s,
            top: baseBottom - maxScaffoldHeight,
            width: 2 * s,
            height: maxScaffoldHeight,
            backgroundColor: gridColor,
            opacity: 0.2,
            transformOrigin: "bottom",
            transform: `scaleY(${scaffoldingProgress})`,
            transition: "none",
          }}
        />
      ))}

      {/* Foundation Base Line */}
      <div
        style={{
          position: "absolute",
          left: marginLeft,
          top: baseBottom + floorGap / 2,
          height: 4 * s,
          width: lineWidth,
          backgroundColor: textColor,
          borderRadius: 2 * s,
          transition: "none",
        }}
      />

      {/* Building Blocks */}
      {blocks.map((block) => {
        const blockProgress = spring({
          frame: frame - block.delay,
          fps,
          config: { damping: 14, mass: 0.8 },
        });
        const blockScale = interpolate(blockProgress, [0, 1], [0.8, 1], {
          extrapolateLeft: "clamp",
        });
        const blockY = interpolate(blockProgress, [0, 1], [40 * s, 0], {
          extrapolateLeft: "clamp",
        });
        const blockOpacity = interpolate(blockProgress, [0, 0.5], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        return (
          <div
            key={block.id}
            style={{
              position: "absolute",
              left: block.x,
              top: block.y,
              width: block.width,
              height: block.height,
              backgroundColor: block.isAccent ? accentColor : blockColor,
              borderRadius: 4 * s,
              opacity: blockOpacity,
              transform: `translateY(${blockY}px) scale(${blockScale})`,
              boxShadow: `0px ${4 * s}px ${12 * s}px rgba(0,0,0,0.06)`,
              border: `1px solid rgba(0,0,0,0.02)`,
              transition: "none",
            }}
          />
        );
      })}

      {/* Left Text Content Area */}
      <div
        style={{
          position: "absolute",
          left: width * 0.05,
          top: height * 0.35,
          width: width * 0.3,
          display: "flex",
          flexDirection: "column",
          gap: 24 * s,
        }}
      >
        <div
          style={{
            height: 6 * s,
            width: accentLineWidth,
            backgroundColor: accentColor,
            borderRadius: 3 * s,
            transition: "none",
          }}
        />
        <h1
          style={{
            fontFamily: playfairFamily,
            fontSize: 72 * s,
            fontWeight: 700,
            lineHeight: 1.1,
            color: textColor,
            margin: 0,
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            transition: "none",
          }}
        >
          {title}
        </h1>
        <p
          style={{
            fontFamily: interFamily,
            fontSize: 32 * s,
            fontWeight: 400,
            lineHeight: 1.5,
            color: textColor,
            opacity: subtitleOpacity * 0.7,
            margin: 0,
            transform: `translateY(${subtitleY}px)`,
            transition: "none",
          }}
        >
          {subtitle}
        </p>
      </div>
    </AbsoluteFill>
  );
};

export default BuildingFromTheGroundUp;